SELECT qryStatistikElementeUnAbweichung3.Elektrolyseur, qryStatistikElementeUnAbweichung3.Datum, qryStatistikElementeUnAbweichung3.Zeit, qryStatistikElementeUnAbweichung3.[I Gesamt], qryStatistikElementeUnAbweichung3.i, qryStatistikElementeUnAbweichung3.Cc, qryStatistikElementeUnAbweichung3.[t An], qryStatistikElementeUnAbweichung3.[t Ka], qryStatistikElementeUnAbweichung3.tm, qryStatistikElementeUnAbweichung3.Uo, qryStatistikElementeUnAbweichung3.Position, qryStatistikElementeUnAbweichung3.Ui, qryStatistikElementeUnAbweichung3.Uk, qryStatistikElementeUnAbweichung3.Unalt, qryStatistikElementeUnAbweichung3.UnVgl3, qryStatistikElementeUnAbweichung3.iRef, qryStatistikElementeUnAbweichung3.tKorr, qryStatistikElementeUnAbweichung3.cKorr, qryStatistikElementeUnAbweichung3.Un, qryStatistikElementeUnAbweichung2.UnMittel, ([Un]-[UnMittel])*1000 AS Abweichung
FROM tblGewDaten, qryStatistikElementeUnAbweichung3 INNER JOIN qryStatistikElementeUnAbweichung2 ON qryStatistikElementeUnAbweichung3.Elektrolyseur = qryStatistikElementeUnAbweichung2.Elektrolyseur
WHERE (((([Un]-[UnMittel])*1000)>[tblGewDaten].[AbweichungUn]))
ORDER BY qryStatistikElementeUnAbweichung3.Elektrolyseur, qryStatistikElementeUnAbweichung3.Position;
